BEGIN IMMEDIATE;
CREATE TABLE IF NOT EXISTS users(name TEXT PRIMARY KEY, salt BLOB NOT NULL, digest BLOB NOT NULL, role TEXT NOT NULL, department TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, name TEXT NOT NULL REFERENCES users(name), expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS extensions(number TEXT PRIMARY KEY, kind TEXT NOT NULL, label TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS calls(id TEXT PRIMARY KEY, source TEXT NOT NULL, external_id TEXT NOT NULL, caller TEXT NOT NULL, callee TEXT NOT NULL, started TEXT NOT NULL, room TEXT NOT NULL, direction TEXT NOT NULL, filename TEXT NOT NULL, stored TEXT NOT NULL, duration REAL, test INTEGER NOT NULL, status TEXT NOT NULL, error TEXT NOT NULL DEFAULT '', segments TEXT NOT NULL DEFAULT '[]', UNIQUE(source,external_id));
CREATE TABLE IF NOT EXISTS items(id INTEGER PRIMARY KEY, call_id TEXT NOT NULL REFERENCES calls(id), title TEXT NOT NULL, department TEXT NOT NULL, quote TEXT NOT NULL, start REAL NOT NULL, state TEXT NOT NULL DEFAULT '待确认');
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY, item INTEGER UNIQUE NOT NULL REFERENCES items(id), title TEXT NOT NULL, room TEXT NOT NULL, department TEXT NOT NULL, state TEXT NOT NULL, due REAL NOT NULL);
CREATE TABLE IF NOT EXISTS history(id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), actor TEXT NOT NULL, state TEXT NOT NULL, note TEXT NOT NULL, at REAL NOT NULL);
PRAGMA user_version=1;
COMMIT;
